package org.apache.commons.lang;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_createNumber_TriageGen2Test {

    @Test
    public void testNull() throws NumberFormatException {
        assertNull(NumberUtils.createNumber(null));
    }

    @Test(expected = NumberFormatException.class)
    public void testEmptyString() throws NumberFormatException {
        NumberUtils.createNumber("");
    }

    @Test(expected = NumberFormatException.class)
    public void testSingleNonDigit() throws NumberFormatException {
        NumberUtils.createNumber("a");
    }

    @Test
    public void testDoubleDashProtection() throws NumberFormatException {
        assertNull(NumberUtils.createNumber("--123"));
    }

    @Test
    public void testHexadecimal() throws NumberFormatException {
        // Assuming createInteger handles 0x
        assertEquals(Integer.valueOf(10), NumberUtils.createNumber("0x0A"));
        assertEquals(Integer.valueOf(-10), NumberUtils.createNumber("-0x0A"));
    }

    @Test
    public void testIntegerTypes() throws NumberFormatException {
        assertEquals(Integer.valueOf(123), NumberUtils.createNumber("123"));
        assertEquals(Long.valueOf(123L), NumberUtils.createNumber("123"));
        assertEquals(new BigInteger("12345678901234567890"), NumberUtils.createNumber("12345678901234567890"));
    }

    @Test
    public void testDecimalAndExponent() throws NumberFormatException {
        assertEquals(new BigDecimal("123.45"), NumberUtils.createNumber("123.45"));
        assertEquals(new BigDecimal("1.23e2"), NumberUtils.createNumber("1.23e2"));
        assertEquals(new BigDecimal("1.23E2"), NumberUtils.createNumber("1.23E2"));
    }

    @Test(expected = NumberFormatException.class)
    public void testInvalidExponentPosition() throws NumberFormatException {
        // expPos < decPos logic
        NumberUtils.createNumber("1.2e.3"); 
    }

    @Test
    public void testSuffixL() throws NumberFormatException {
        assertEquals(Long.valueOf(123L), NumberUtils.createNumber("123L"));
        assertEquals(Long.valueOf(-123L), NumberUtils.createNumber("-123L"));
        assertEquals(new BigInteger("12345678901234567890"), NumberUtils.createNumber("12345678901234567890L"));
    }

    @Test(expected = NumberFormatException.class)
    public void testInvalidSuffixL() throws NumberFormatException {
        NumberUtils.createNumber("123.45L");
    }

    @Test
    public void testSuffixF() throws NumberFormatException {
        assertEquals(Float.valueOf(123.45f), NumberUtils.createNumber("123.45f"));
    }

    @Test
    public void testSuffixD() throws NumberFormatException {
        assertEquals(Double.valueOf(123.45d), NumberUtils.createNumber("123.45d"));
    }

    @Test
    public void testFloatPrecisionFallthrough() throws NumberFormatException {
        // A very large number that might lose precision in Float, should fall to Double or BigDecimal
        // Using a value that is too large for Float but fits in Double
        String largeVal = "123456789.123456789F"; 
        // The logic checks: if (!(f.isInfinite() || (!allZeros)))
        // If it fails float, it tries Double
        Number result = NumberUtils.createNumber("123456789.123456789F");
        assertTrue(result instanceof Double || result instanceof BigDecimal);
    }

    @Test
    public void testZeroPrecisionLogic() throws NumberFormatException {
        // Test the 'allZeros' logic for 0.0 cases
        assertEquals(Float.valueOf(0.0f), NumberUtils.createNumber("0.0f"));
        assertEquals(Double.valueOf(0.0d), NumberUtils.createNumber("0.0d"));
        // If it's "0.000" but not "allZeros" (if exp is not zero), it tests precision
        assertEquals(new BigDecimal("0.000"), NumberUtils.createNumber("0.000"));
    }

    @Test
    public void testDefaultCase() throws NumberFormatException {
        // Test a suffix that doesn't match L, F, or D
        try {
            NumberUtils.createNumber("123x");
            fail("Should have thrown NumberFormatException");
        } catch (NumberFormatException e) {
            assertTrue(e.getMessage().contains("is not a valid number"));
        }
    }

    @Test
    public void testComplexExponentSuffix() throws NumberFormatException {
        // Testing the logic: if (expPos > -1 && expPos < val.length() - 1)
        // Case like "1.2e3L"
        // numeric = "1.2e3", lastChar = 'L', exp = "3"
        // However, the L case requires dec == null and exp == null
        try {
            NumberUtils.createNumber("1.2e3L");
            fail("Should fail because L requires no decimal/exponent");
        } catch (NumberFormatException e) {
            // expected
        }
    }

    @Test
    public void testBigIntegerFallback() throws NumberFormatException {
        // Test the case where it's not an Integer or Long but is a valid number
        String huge = "999999999999999999999999";
        assertEquals(new BigInteger(huge), NumberUtils.createNumber(huge));
    }

    @Test
    public void testDecimalWithNoExponent() throws NumberFormatException {
        assertEquals(new BigDecimal("123.456"), NumberUtils.createNumber("123.456"));
    }

    @Test
    public void testExponentWithNoDecimal() throws NumberFormatException {
        // Tests the mant = val.substring(0, expPos) logic
        assertEquals(new BigDecimal("123e2"), NumberUtils.createNumber("123e2"));
    }
}
